"""One persisted whole-song event allocation, generated by the local rewriter.

Plans describe intended events, not observations of generated video. Parsing
checks event structure, then allocates events to the actual media timeline.
"""
import hashlib
import json
import re
import uuid
from pathlib import Path

from banana_mv.director import MODES, mode_candidates, performance_scene_modes
from banana_mv.prompt_quality import POLICY, MV_POLICY, ending_excerpt, director_led, DIRECTOR_AUTHORITY

VERSION = 2


def allowed_modes(req):
    if director_led(req):
        return set(MODES)
    candidates, excluded = mode_candidates(req)
    selected = req.get('director', 'auto')
    if selected != 'auto' and selected not in excluded:
        if req.get('optimizer_version',0) >= 1:
            # A main action style still permits performance/band events that
            # the user places in a separate scene.
            return {selected} | performance_scene_modes(req)
        return {selected}
    return candidates or {'performance'}


def validate_plan(raw, segments, req):
    if isinstance(raw, str):
        raw = re.sub(r'<think>.*?</think>', '', raw, flags=re.S).strip()
        raw = re.sub(r'^```(?:json)?\s*|\s*```$', '', raw).strip()
        try:
            raw = json.loads(raw)
        except ValueError as error:
            raise ValueError('全曲規劃不是有效 JSON') from error
    if not isinstance(raw, dict):
        raise ValueError('全曲規劃缺少事件清單')
    # Accept older 9B segment-shaped responses too. Model indices/counts are
    # suggestions, never the authority for slicing source audio or video.
    rows = raw.get('events', raw.get('segments'))
    if rows is None and isinstance(raw.get('event'),str):
        rows = [raw]
    if not isinstance(rows, list) or not 1 <= len(rows) <= 128:
        raise ValueError('全曲規劃需要 1–128 個事件')
    events = []
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError('全曲規劃事件格式不符')
        event = row.get('event')
        if not isinstance(event, str) or not event.strip() or len(event.strip()) > 800:
            raise ValueError('全曲規劃需有簡潔、具體的各段事件')
        mode = row.get('mode')
        if not isinstance(mode,str) or mode not in MODES:
            raise ValueError('全曲規劃的導演模式代碼無效')
        events.append({'event': event.strip(), 'mode': mode})
    result = [dict(row,index=seg['index']) for seg,row in zip(segments,events)] if len(events)==len(segments) else []
    return {'version': VERSION, 'events': events, 'segments': result}


def fit_events(cfg, req, segments, source_events, parts, rewrite):
    """Ask 9B for concrete connecting developments, never percentage padding.

    The application owns the target slots. Existing opening/final anchors remain;
    only missing slots require expansion. Excess events are condensed in order.
    """
    total, count = len(segments), len(source_events)
    if count == total:
        return [dict(row,index=seg['index']) for seg,row in zip(segments,source_events)]
    slots = [None]*total
    groups = [[] for _ in segments]
    if 1 < count < total:
        for i,event in enumerate(source_events):
            slots[round(i*(total-1)/(count-1))] = event
    elif count > total:
        for i in range(total):
            groups[i] = source_events[i*count//total:(i+1)*count//total]
            if len(groups[i]) == 1:
                slots[i] = groups[i][0]
    # A single whole-story event must be expanded across all slots, not placed
    # intact at the start where it would prematurely resolve the entire story.
    for i,seg in enumerate(segments):
        if slots[i] is not None:
            continue
        previous = [row['event'] for row in slots[max(0,i-3):i] if row]
        upcoming = next((row['event'] for row in slots[i+1:] if row), None)
        task = {'target_clip':i+1,'clip_count':total,'seconds':seg['seconds'],
                'previous_allocated_developments':previous,'next_reserved_event':upcoming,
                'original_ordered_events':source_events,
                'events_to_condense_here':groups[i],
                'final_clip':i==total-1}
        instruction = ("Write ONE concrete visual development for the target clip, based on the user's existing story. "
                       "Return ONLY JSON: {\"event\":\"specific action and observable response\",\"mode\":\"performance\"}. "
                       "Use an Allowed visual mode. Event length 8–800 characters. "
                       "Develop the causal bridge between previous and next events: a new action, interaction, defense, "
                       "reaction or changing situation consistent with the supplied content. "
                       "Do not pad with generic waiting, slow motion, repeated summaries, percentages or numbered placeholders. "
                       "Do not add unrelated plot, new characters, locations or powers. Respect immediate action if requested. "
                       "If events_to_condense_here is populated, condense those events in order into one feasible clip. "
                       "Do not repeat an allocated event or perform the next reserved event early. "
                       "Only the final clip may deliver the whole-story final resolution. Short tails need less action.")
        if director_led(req):
            instruction=('Write ONE music-video beat for the target clip as the creative director. '
                         'Return ONLY JSON: {"event":"concrete visual beat","mode":"performance"}. '
                         'Use a supported mode code and concise nonempty event. Shape the pacing from the '
                         'whole-song music profile and surrounding treatment, not the paragraph order of the user outline. '
                         'You may add compatible developments, contrasts or performance cuts; use the supplied '
                         'source-event group as material to condense when present.\n'+DIRECTOR_AUTHORITY)
        if req.get('optimizer_version',0)>=1:
            instruction += ('\n'+MV_POLICY+'\nA missing slot may be developed as performance, reaction or a contrasting '
                            'cut within the supplied material; do not invent an in-world causal bridge between separate scenes.')
        attempt_parts = parts + [('text','\nCONTENT-BASED COMPLETION TASK:\n'+json.dumps(task,ensure_ascii=False))]
        for attempt in range(2):
            raw = rewrite(cfg,instruction,attempt_parts,uuid.uuid4().hex[:8])
            try:
                candidates = validate_plan(raw,segments,req)['events']
                slots[i] = candidates[0];break
            except ValueError as error:
                if attempt:
                    raise ValueError(f'9B 第 {i+1} 段內容補寫失敗：{error}') from error
                attempt_parts += [('text','\nCorrect the event format/content: '+str(error))]
    return [dict(row,index=seg['index']) for seg,row in zip(segments,slots)]


def plan_input(req, segments):
    timeline = []
    for seg in segments:
        evidence = seg.get('audio_evidence', {})
        timeline.append({'index':seg['index'], 'start':seg['start'], 'seconds':seg['seconds'],
                         'energy':evidence.get('relative_energy'),
                         'change_db':evidence.get('energy_change_db'),
                         'local_accents':evidence.get('transient_candidates_s', [])[:4]})
    title=('USER CREATIVE BRIEF (outline for director interpretation; preserve reference roles and explicit hard restrictions):\n'
           if director_led(req) else 'USER WHOLE-SONG BRIEF (highest priority, do not change roles or exclusions):\n')
    return (title + req.get('prompt', '')
            + '\nUser-supplied lyrics as context only; do not add or rewrite lyrics:\n' + req.get('lyrics', '')
            + '\nAllowed visual modes: ' + ', '.join(sorted(allowed_modes(req)))
            + '\nRequested intensity: ' + req.get('intensity', 'high')
            + '\nMEASURED TIMELINE (null means unmeasured, not silence):\n' + json.dumps(timeline, ensure_ascii=False)
            + ('\n'+POLICY+'\n'+MV_POLICY+'\nAssign performance/band modes to performance-scene events even when action is the selected main style. '
               'Use action only for actual fight events. Never transfer a scene-specific singing prohibition to all scenes.'
               if req.get('optimizer_version',0)>=1 else '')
            + ('\n'+DIRECTOR_AUTHORITY if director_led(req) else ''))


SYSTEM = '''Allocate the user's whole-song MV brief into an ordered sequence of story events.
Return ONLY JSON: {"events":[{"event":"concrete action and visible consequence","mode":"performance"}]}.
Write as many meaningful events as the brief needs, from 1 to 128. Do NOT match a required number of clips or invent segment indices.
The application automatically fits this sequence to the actual audio duration and clip boundaries.
Each event must be 8–800 characters, preferably one short sentence. If useful, split a complex event into distinct causal developments.
Do not add characters, powers, genres, places or plot twists outside the user brief.
Preserve singer identities, voice assignments, reference roles, costumes, recurring locations and all user exclusions.
Keep the same venue if requested; repeating a location or a singer is allowed, resetting an event is not.
Give every segment a distinct development, interaction, consequence or evolving performance phrase. Do not retell the entire plot in every segment.
Reserve the user's final resolution for the last segment; preceding clips may have local payoffs without ending the whole story.
For a performance-only brief, vary purposeful actions and interactions naturally; do not invent a separate narrative.
Select only from Allowed visual modes. In auto mode, different segments may use different supported modes. Explicit mode selections must be respected.
Use acoustic rise/quiet/accent evidence to shape contrast, but do not infer lyrics, emotion, instruments or choruses from energy.
Do not output shot lists, mandatory cuts, media tokens, music, new lyrics or analysis commentary. These are planned events, not verified generated events.'''


def ensure_plan(cfg, req, segments, originals, work, rewrite):
    """Plan once, then complete missing content in application-owned clip slots."""
    content = plan_input(req, segments)
    fingerprint = hashlib.sha256(content.encode()).hexdigest()
    path = Path(work)/'director_plan.json'
    if path.is_file():
        saved = json.loads(path.read_text(encoding='utf-8'))
        if saved.get('version') != VERSION or saved.get('input_sha256') != fingerprint:
            raise ValueError('已存全曲規劃與此專案不符，請另建專案，避免續跑混用事件。')
        validated = validate_plan(saved, segments, req)
        if not validated['segments']:
            raise ValueError('已存規劃不完整，請檢查專案檔案。')
        validated['input_sha256'] = fingerprint
        return validated
    from PIL import Image, ImageOps
    parts = [('text', content)]
    for index, original in enumerate(originals, 1):
        with Image.open(original) as image:
            image = ImageOps.exif_transpose(image).convert('RGB')
            image.thumbnail((768,768))
            parts.extend([('text', f'\nUser reference image {index}: '), ('image', image.copy())])
    for attempt in range(2):
        system = SYSTEM + ('\nPriority MV interpretation:\n'+MV_POLICY if req.get('optimizer_version',0)>=1 else '')
        if director_led(req):
            system=('Create a director treatment for the complete source song using its measured music profile. '
                    'Return ONLY JSON: {"events":[{"event":"concrete visual beat","mode":"performance"}]}. '
                    'Write 1–128 concise nonempty events. Clip indices/counts are handled by the application. '
                    'You may intercut, reorder, expand or condense compatible material and vary scene modes '
                    'to serve musical rhythm; do not merely translate each outline paragraph into a shot. '
                    'Acoustic cues do not identify unprovided lyrics or song-section names.\n'
                    +DIRECTOR_AUTHORITY+'\n'+POLICY+'\n'+MV_POLICY)
        elif req.get('optimizer_version',0)>=1:
            terminal=ending_excerpt(req.get('prompt',''))
            if terminal:
                system += ('\nThe last planned event must preserve the following user ending, including '
                           'its terminal shot AFTER any preceding climax. Do not substitute a different ending; '
                           'reserve it for the final song window.\nUSER ENDING VERBATIM:\n'+terminal)
        raw = rewrite(cfg, system, parts, uuid.uuid4().hex[:8])
        try:
            plan = validate_plan(raw, segments, req)
            break
        except ValueError as error:
            if attempt:
                raise ValueError('9B 全曲事件規劃失敗：' + str(error) + '；可關閉全曲事件規劃後另建專案。') from error
            parts = parts + [('text', '\nYour previous response failed validation: ' + str(error)
                             + '\nReturn a fresh JSON events list in narrative order. No required segment count or indices. No markdown. '
                             + '\nPrevious response:\n' + str(raw)[:16000])]
    if not plan['segments']:
        source_events = plan['events']
        plan['segments'] = fit_events(cfg,req,segments,source_events,parts,rewrite)
        plan['source_events'] = source_events
        plan['events'] = [{'event':row['event'],'mode':row['mode']} for row in plan['segments']]
    plan['input_sha256'] = fingerprint
    temp = path.with_suffix('.tmp')
    temp.write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding='utf-8')
    temp.replace(path)
    return plan


def plan_context(segment, creative=False):
    row = segment.get('director_plan')
    if not row:
        return ''
    if creative:
        text=('DIRECTOR TREATMENT — CURRENT CLIP: '+row['event']
              +'\nUse this musical beat as your creative starting point; restage action, framing and cut order '
              'as needed within this clip. Preserve reference roles and explicit hard restrictions. '
              'The complete user outline is material, not a mandatory shot sequence.')
    else:
        text = ('CURRENT SEGMENT EVENT ALLOCATION (the user brief still governs roles and exclusions): '
            + row['event'] + '\nDevelop ONLY this allocated event, with a readable action and consequence. '
            'Other whole-song events are reserved for their own intervals; do not restart the opening or jump to the finale.')
    previous = segment.get('previous_planned_event')
    if previous:
        text += '\nPrevious planned event (not visually verified): ' + previous + '\nAdvance from its intended outcome; do not replay it.'
    return text
